  // The headline is the strongest reason for the call: a coordination signal, or for "likely
  // organic" the safeguard that held. Parentheticals are method detail; the Evidence card keeps them.
  const headline = (c, sigs = c.top_signals || []) => {
    const list = sigs.filter((s) => s.summary).slice().sort((a, b) => (num(b.score) || 0) - (num(a.score) || 0));
    const guard = c.status === 'likely_organic' && list.find((s) => s.polarity === 'against' && fired(s));
    const best = guard || list.find((s) => s.polarity !== 'against' && fired(s)) || list[0];
    return best ? tidy(best.summary).replace(/\s*\([^)]*\)\s*$/, '').replace(/^./, (x) => x.toUpperCase()) : `${plural(c.size || 0, 'account')} grouped together`;
  };

